        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = self.parse_datatype()?;
        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;
        while let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Primary => { self.expect(Token::Keyword(Keyword::Key))?; primary_key = true; }
                Keyword::Not => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(false); }
                Keyword::Null => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(true); }
                Keyword::Default => { default = Some(self.parse_expression()?); }
                Keyword::Unique => { unique = true; }
                Keyword::Index => { index = true; }
                Keyword::References => { references = Some(self.next_ident()?); }
                _ => return Err(errinput!("unexpected keyword {kw} in column definition")),
            }
        }
        Ok(ast::Column { name, datatype, primary_key, nullable, default, unique, index, references })
    }

    fn parse_datatype(&mut self) -> Result<DataType> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(match kw {
                Keyword::Bool | Keyword::Boolean => DataType::Boolean,
                Keyword::Int | Keyword::Integer => DataType::Integer,
                Keyword::Float | Keyword::Double => DataType::Float,
                Keyword::String | Keyword::Text | Keyword::Varchar => DataType::String,
                _ => return Err(errinput!("unexpected keyword {kw}")),
            })
        } else {
            Err(errinput!("expected data type"))
        }
    }

    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        let mut if_exists = false;
        if self.next_if_keyword() == Some(Keyword::If) {
            self.expect(Token::Keyword(Keyword::Exists))?;
            if_exists = true;
