        select.push(self.parse_select_item()?);
        while self.next_is(Token::Comma) {
            select.push(self.parse_select_item()?);
        }
        Ok(select)
    }

    fn parse_select_item(&mut self) -> Result<(ast::Expression, Option<String>)> {
        let expr = self.parse_expression()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
