        if self.next_is(Token::Period) {
            let column = self.next_ident()?;
            Ok(ast::Expression::Column(Some(table), column))
        } else {
            Ok(ast::Expression::Column(None, table))
        }
    }

    fn parse_expression_list(&mut self) -> Result<Vec<ast::Expression>> {
        let mut exprs = Vec::new();
        exprs.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            exprs.push(self.parse_expression()?);
        }
        Ok(exprs)
    }

    fn parse_prefix_operator_at(&mut self, _min_precedence: Precedence) -> Option<PrefixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::Not => Some(PrefixOperator::Not),
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let _lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::NaN) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return None;
                    };
                    if neg { Some(PrefixOperator::Not) } else { None }
                }
                _ => None,
            };
        }
        if self.next_is(Token::Minus) { return Some(PrefixOperator::Minus); }
        if self.next_is(Token::Plus) { return Some(PrefixOperator::Plus); }
        None
    }

    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::And => Some(InfixOperator::And),
                Keyword::Or => Some(InfixOperator::Or),
                Keyword::Like => Some(InfixOperator::Like),
                _ => None,
            };
        }
        if self.next_is(Token::Equal) { return Some(InfixOperator::Equal); }
        if self.next_is(Token::NotEqual) { return Some(InfixOperator::NotEqual); }
        if self.next_is(Token::GreaterThan) { return Some(InfixOperator::GreaterThan); }
        if self.next_is(Token::GreaterThanOrEqual) { return Some(InfixOperator::GreaterThanOrEqual); }
        if self.next_is(Token::LessThan) { return Some(InfixOperator::LessThan); }
        if self.next_is(Token::LessThanOrEqual) { return Some(InfixOperator::LessThanOrEqual); }
        if self.next_is(Token::Plus) { return Some(InfixOperator::Add); }
        if self.next_is(Token::Minus) { return Some(InfixOperator::Subtract); }
        if self.next_is(Token::Asterisk) { return Some(InfixOperator::Multiply); }
        if self.next_is(Token::Slash) { return Some(InfixOperator::Divide); }
        if self.next_is(Token::Caret) { return Some(InfixOperator::Exponentiate); }
        if self.next_is(Token::Percent) { return Some(InfixOperator::Remainder); }
        None
    }

    fn parse_postfix_operator_at(&mut self, _min_precedence: Precedence) -> Result<Option<PostfixOperator>> {
        if self.next_is(Token::Exclamation) {
            return Ok(Some(PostfixOperator::Factorial));
        }
        if self.next_is(Token::Keyword(Keyword::Is)) {
            let neg = self.next_is(Token::Keyword(Keyword::Not));
            let lit = if self.next_is(Token::Keyword(Keyword::Null)) {
                ast::Literal::Null
            } else if self.next_is(Token::Keyword(Keyword::NaN)) {
                ast::Literal::Float(f64::NAN)
            } else {
                return Err(errinput!("expected NULL or NAN"));
            };
            return Ok(Some(if neg { PostfixOperator::IsNot(lit) } else { PostfixOperator::Is(lit) }));
        }
        Ok(None)
    }
}

type Precedence = u8;

enum Associativity { Left, Right }

impl Add<Associativity> for Precedence {
    type Output = Self;
    fn add(self, rhs: Associativity) -> Self {
        match rhs { Associativity::Left => self + 1, Associativity::Right => self }
    }
}

enum PrefixOperator { Minus, Not, Plus }

impl PrefixOperator {
    fn precedence(&self) -> Precedence { 100 }
    fn associativity(&self) -> Associativity { Associativity::Right }
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Minus => ast::Expression::Operator(ast::Operator::Negate(Box::new(rhs))),
            Self::Not => ast::Expression::Operator(ast::Operator::Not(Box::new(rhs))),
            Self::Plus => ast::Expression::Operator(ast::Operator::Identity(Box::new(rhs))),
        }
    }
}

enum InfixOperator {
    Add, And, Divide, Equal, Exponentiate, GreaterThan, GreaterThanOrEqual,
    LessThan, LessThanOrEqual, Like, Multiply, NotEqual, Or, Remainder, Subtract,
}

impl InfixOperator {
    fn precedence(&self) -> Precedence {
        match self {
            Self::Or => 10, Self::And => 20,
            Self::Equal | Self::NotEqual | Self::LessThan | Self::LessThanOrEqual |
            Self::GreaterThan | Self::GreaterThanOrEqual | Self::Like => 30,
            Self::Add | Self::Subtract => 40,
            Self::Multiply | Self::Divide | Self::Remainder => 50,
            Self::Exponentiate => 60,
        }
    }
    fn associativity(&self) -> Associativity { Associativity::Left }
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Add => ast::Expression::Operator(Add(Box::new(lhs), Box::new(rhs))),
            Self::And => ast::Expression::Operator(And(Box::new(lhs), Box::new(rhs))),
            Self::Divide => ast::Expression::Operator(Divide(Box::new(lhs), Box::new(rhs))),
            Self::Equal => ast::Expression::Operator(Equal(Box::new(lhs), Box::new(rhs))),
            Self::Exponentiate => ast::Expression::Operator(Exponentiate(Box::new(lhs), Box::new(rhs))),
            Self::GreaterThan => ast::Expression::Operator(GreaterThan(Box::new(lhs), Box::new(rhs))),
            Self::GreaterThanOrEqual => ast::Expression::Operator(GreaterThanOrEqual(Box::new(lhs), Box::new(rhs))),
            Self::LessThan => ast::Expression::Operator(LessThan(Box::new(lhs), Box::new(rhs))),
            Self::LessThanOrEqual => ast::Expression::Operator(LessThanOrEqual(Box::new(lhs), Box::new(rhs))),
            Self::Like => ast::Expression::Operator(Like(Box::new(lhs), Box::new(rhs))),
            Self::Multiply => ast::Expression::Operator(Multiply(Box::new(lhs), Box::new(rhs))),
            Self::NotEqual => ast::Expression::Operator(NotEqual(Box::new(lhs), Box::new(rhs))),
            Self::Or => ast::Expression::Operator(Or(Box::new(lhs), Box::new(rhs))),
            Self::Remainder => ast::Expression::Operator(Remainder(Box::new(lhs), Box::new(rhs))),
            Self::Subtract => ast::Expression::Operator(Subtract(Box::new(lhs), Box::new(rhs))),
        }
    }
}

enum PostfixOperator { Factorial, Is(ast::Literal), IsNot(ast::Literal) }

impl PostfixOperator {
    fn precedence(&self) -> Precedence { 70 }
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Factorial => ast::Expression::Operator(Factorial(Box::new(lhs))),
            Self::Is(lit) => ast::Expression::Operator(Is(Box::new(lhs), lit)),
            Self::IsNot(lit) => {
                let is_expr = ast::Expression::Operator(Is(Box::new(lhs), lit));
                ast::Expression::Operator(Not(Box::new(is_expr)))
            }
        }
    }
}
