            if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = op.into_expression(lhs);
                continue;
            }
            break;
        }
        Ok(lhs)
    }

    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::True => ast::Expression::Literal(ast::Literal::Boolean(true)),
                Keyword::False => ast::Expression::Literal(ast::Literal::Boolean(false)),
                Keyword::Null => ast::Expression::Literal(ast::Literal::Null),
                Keyword::Infinity => ast::Expression::Literal(ast::Literal::Float(f64::INFINITY)),
                Keyword::NaN => ast::Expression::Literal(ast::Literal::Float(f64::NAN)),
                Keyword::Select => return Err(errinput!("subqueries not supported yet")),
                _ => return Err(errinput!("unexpected keyword {kw}")),
            });
        }
        if self.next_is(Token::OpenParen) {
            let expr = self.parse_expression()?;
            self.expect(Token::CloseParen)?;
            return Ok(expr);
        }
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::Not => {
                    let expr = self.parse_expression()?;
                    ast::Expression::Operator(ast::Operator::Not(Box::new(expr)))
                }
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::NaN) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return Err(errinput!("expected NULL or NAN"));
                    };
                    if neg {
                        ast::Expression::Operator(ast::Operator::Not(Box::new(
                            ast::Expression::Operator(ast::Operator::Is(
                                Box::new(ast::Expression::All),
                                lit,
                            )),
                        )))
                    } else {
                        ast::Expression::Operator(ast::Operator::Is(Box::new(ast::Expression::All), lit))
                    }
                }
                _ => return Err(errinput!("unexpected keyword {kw}")),
            });
        }
        if self.next_is(Token::Minus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Negate(Box::new(expr))));
        }
        if self.next_is(Token::Plus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Identity(Box::new(expr))));
        }
        let token = match self.lexer.next() {
            Some(Ok(t)) => t,
            Some(Err(e)) => return Err(e),
            None => return Err(errinput::<String>("unexpected end of input")),
        };
        match token {
            Token::Number(s) => {
                return Ok(ast::Expression::Literal(match s.chars().position(|c| c == '.') {
                    Some(_) => ast::Literal::Float(s.parse::<f64>().map_err(|_| errinput::<String>("invalid float"))?),
                    None => ast::Literal::Integer(s.parse::<i64>().map_err(|_| errinput::<String>("invalid integer"))?),
