use std::collections::BTreeMap;
use std::iter::Peekable;
use std::ops::Add;

use super::{Keyword, Lexer, Token, ast};
use crate::errinput;
use crate::error::Result;
use crate::sql::types::DataType;

pub struct Parser<'a> {
    pub lexer: Peekable<Lexer<'a>>,
}

impl Parser<'_> {
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Parser::new(statement);
        let stmt = parser.parse_statement()?;
        parser.skip(Token::Semicolon);
        if parser.peek()?.is_some() {
            return Err(errinput!("unexpected tokens after statement"));
        }
        Ok(stmt)
    }

    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Parser::new(expr);
        let expr = parser.parse_expression()?;
        if parser.peek()?.is_some() {
            return Err(errinput!("unexpected tokens after expression"));
        }
        Ok(expr)
    }

    fn new(input: &str) -> Parser<'_> {
        Parser {
            lexer: Lexer::new(input).peekable(),
        }
    }

    fn next(&mut self) -> Result<Token> {
        match self.lexer.next() {
            Some(Ok(t)) => Ok(t),
            Some(Err(e)) => Err(e),
            None => Err(errinput::<String>("unexpected end of input")),
        }
    }

    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Err(errinput!("expected identifier, got keyword {k}")),
            t => Err(errinput!("expected identifier, got {t}")),
        }
    }

    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        if let Some(Ok(t)) = self.lexer.next() {
            if predicate(&t) {
                Some(t)
            } else {
                self.lexer = std::iter::once(Ok(t)).chain(self.lexer.by_ref()).peekable();
                None
            }
        } else {
            None
        }
    }

    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        if let Some(Ok(t)) = self.lexer.next() {
            f(&t)
        } else {
            None
        }
    }

    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.next_if(|t| matches!(t, Token::Keyword(_))).and_then(|t| {
            if let Token::Keyword(k) = t {
                Some(k)
            } else {
                None
            }
        })
    }

    fn next_is(&mut self, token: Token) -> bool {
        self.next_if(|t| *t == token).is_some()
    }

    fn expect(&mut self, expect: Token) -> Result<()> {
        if self.next_is(expect.clone()) {
            Ok(())
        } else {
            Err(errinput!("expected {expect}, got {:?}", self.peek()?))
        }
    }

    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek().and_then(|r| r.as_ref().ok()))
    }

    fn parse_statement(&mut self) -> Result<ast::Statement> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Begin => self.parse_begin(),
                Keyword::Commit => self.parse_commit(),
                Keyword::Rollback => self.parse_rollback(),
                Keyword::Explain => self.parse_explain(),
                Keyword::Create => self.parse_create_table(),
                Keyword::Drop => self.parse_drop_table(),
                Keyword::Delete => self.parse_delete(),
                Keyword::Insert => self.parse_insert(),
                Keyword::Update => self.parse_update(),
                Keyword::Select => self.parse_select(),
                _ => Err(errinput!("unexpected keyword {kw}")),
            }
        } else {
            Err(errinput!("expected SQL statement"))
        }
    }

    fn parse_begin(&mut self) -> Result<ast::Statement> {
        let mut read_only = false;
        let mut as_of = None;
        if self.next_if_keyword() == Some(Keyword::Read) {
            self.expect(Token::Keyword(Keyword::Write))?;
            read_only = true;
        }
        if self.next_if_keyword() == Some(Keyword::As) {
            self.expect(Token::Keyword(Keyword::Of))?;
            let version = self.next_ident()?;
            as_of = Some(version.parse::<u64>().map_err(|_| errinput::<String>("invalid version"))?);
        }
        Ok(ast::Statement::Begin { read_only, as_of })
    }

    fn parse_commit(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Commit)
    }

    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Rollback)
    }

    fn parse_explain(&mut self) -> Result<ast::Statement> {
        let stmt = self.parse_statement()?;
        Ok(ast::Statement::Explain(Box::new(stmt)))
    }

    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        self.expect(Token::OpenParen)?;
        let mut columns = Vec::new();
        if !self.next_is(Token::CloseParen) {
            columns.push(self.parse_create_table_column()?);
            while self.next_is(Token::Comma) {
                columns.push(self.parse_create_table_column()?);
            }
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = self.parse_datatype()?;
        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;
        while let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Primary => { self.expect(Token::Keyword(Keyword::Key))?; primary_key = true; }
                Keyword::Not => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(false); }
                Keyword::Null => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(true); }
                Keyword::Default => { default = Some(self.parse_expression()?); }
                Keyword::Unique => { unique = true; }
                Keyword::Index => { index = true; }
                Keyword::References => { references = Some(self.next_ident()?); }
                _ => return Err(errinput!("unexpected keyword {kw} in column definition")),
            }
        }
        Ok(ast::Column { name, datatype, primary_key, nullable, default, unique, index, references })
    }

    fn parse_datatype(&mut self) -> Result<DataType> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(match kw {
                Keyword::Bool | Keyword::Boolean => DataType::Boolean,
                Keyword::Int | Keyword::Integer => DataType::Integer,
                Keyword::Float | Keyword::Double => DataType::Float,
                Keyword::String | Keyword::Text | Keyword::Varchar => DataType::String,
                _ => return Err(errinput!("unexpected keyword {kw}")),
            })
        } else {
            Err(errinput!("expected data type"))
        }
    }

    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        let mut if_exists = false;
        if self.next_if_keyword() == Some(Keyword::If) {
            self.expect(Token::Keyword(Keyword::Exists))?;
            if_exists = true;
        }
        Ok(ast::Statement::DropTable { name, if_exists })
    }

    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::From))?;
        let table = self.next_ident()?;
        let mut rwhere = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            rwhere = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Delete { table, rwhere })
    }

    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Into))?;
        let table = self.next_ident()?;
        let mut columns = None;
        self.expect(Token::OpenParen)?;
        if !self.next_is(Token::CloseParen) {
            columns = Some(vec![self.next_ident()?]);
            while self.next_is(Token::Comma) {
                columns.as_mut().unwrap().push(self.next_ident()?);
            }
        }
        self.expect(Token::CloseParen)?;
        self.expect(Token::Keyword(Keyword::Values))?;
        self.expect(Token::OpenParen)?;
        let mut values = Vec::new();
        values.push(self.parse_expression_list()?);
        while self.next_is(Token::Comma) {
            values.push(self.parse_expression_list()?);
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::Insert { table, columns, values })
    }

    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;
        self.expect(Token::Keyword(Keyword::Set))?;
        let mut set = BTreeMap::new();
        let col = self.next_ident()?;
        set.insert(col.clone(), None);
        self.expect(Token::Equal)?;
        set.get_mut(&col).unwrap().replace(self.parse_expression()?);
        let mut rwhere = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            rwhere = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Update { table, set, rwhere })
    }

    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;
        let from = self.parse_from_clause()?;
        let rwhere = self.parse_where_clause()?;
        let group_by = self.parse_group_by_clause()?;
        let having = self.parse_having_clause()?;
        let order_by = self.parse_order_by_clause()?;
        let offset = self.parse_offset_clause()?;
        let limit = self.parse_limit_clause()?;
        Ok(ast::Statement::Select { select, from, rwhere, group_by, having, order_by, offset, limit })
    }

    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        select.push(self.parse_select_item()?);
        while self.next_is(Token::Comma) {
            select.push(self.parse_select_item()?);
        }
        Ok(select)
    }

    fn parse_select_item(&mut self) -> Result<(ast::Expression, Option<String>)> {
        let expr = self.parse_expression()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if let ast::Expression::Column(None, name) = &expr {
            if self.next_if_keyword() != Some(Keyword::As) {
                alias = Some(name.clone());
            }
        }
        Ok((expr, alias))
    }

    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        self.expect(Token::Keyword(Keyword::From))?;
        let mut from = Vec::new();
        from.push(self.parse_from_table()?);
        while let Some(join_type) = self.parse_from_join()? {
            let right = self.parse_from_table()?;
            let mut predicate = None;
            if self.next_if_keyword() == Some(Keyword::On) {
                predicate = Some(self.parse_expression()?);
            }
            from.push(ast::From::Join { left: Box::new(from.pop().unwrap()), right: Box::new(right), r#type: join_type, predicate });
        }
        Ok(from)
    }

    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if alias.is_none() {
            alias = Some(name.clone());
        }
        Ok(ast::From::Table { name, alias })
    }

    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(Some(match kw {
                Keyword::Cross => ast::JoinType::Cross,
                Keyword::Inner => ast::JoinType::Inner,
                Keyword::Left => ast::JoinType::Left,
                Keyword::Right => ast::JoinType::Right,
                Keyword::Join => ast::JoinType::Inner,
                _ => return Err(errinput!("unexpected keyword {kw}")),
            }))
        } else {
            Ok(None)
        }
    }

    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Where) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        self.expect(Token::Keyword(Keyword::Group))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut group_by = Vec::new();
        group_by.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            group_by.push(self.parse_expression()?);
        }
        Ok(group_by)
    }

    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Having) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        self.expect(Token::Keyword(Keyword::Order))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut order_by = Vec::new();
        order_by.push(self.parse_order_by_item()?);
        while self.next_is(Token::Comma) {
            order_by.push(self.parse_order_by_item()?);
        }
        Ok(order_by)
    }

    fn parse_order_by_item(&mut self) -> Result<(ast::Expression, ast::Direction)> {
        let expr = self.parse_expression()?;
        let mut direction = ast::Direction::Ascending;
        if self.next_if_keyword() == Some(Keyword::Desc) {
            direction = ast::Direction::Descending;
        } else if self.next_if_keyword() == Some(Keyword::Asc) {
            direction = ast::Direction::Ascending;
        }
        Ok((expr, direction))
    }

    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Limit) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Offset) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::MIN)
    }

    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        let mut lhs = self.parse_expression_atom()?;
        loop {
            if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
                lhs = op.into_expression(lhs);
                continue;
            }
            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs_precedence = min_precedence + op.associativity();
                let rhs = self.parse_expression_at(rhs_precedence)?;
                lhs = op.into_expression(lhs, rhs);
                continue;
            }
            if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = op.into_expression(lhs);
                continue;
            }
            break;
        }
        Ok(lhs)
    }

    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::True => ast::Expression::Literal(ast::Literal::Boolean(true)),
                Keyword::False => ast::Expression::Literal(ast::Literal::Boolean(false)),
                Keyword::Null => ast::Expression::Literal(ast::Literal::Null),
                Keyword::Infinity => ast::Expression::Literal(ast::Literal::Float(f64::INFINITY)),
                Keyword::NaN => ast::Expression::Literal(ast::Literal::Float(f64::NAN)),
                Keyword::Select => return Err(errinput!("subqueries not supported yet")),
                _ => return Err(errinput!("unexpected keyword {kw}")),
            });
        }
        if self.next_is(Token::OpenParen) {
            let expr = self.parse_expression()?;
            self.expect(Token::CloseParen)?;
            return Ok(expr);
        }
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
