        let mut columns = Vec::new();
        if !self.next_is(Token::CloseParen) {
            columns.push(self.parse_create_table_column()?);
            while self.next_is(Token::Comma) {
                columns.push(self.parse_create_table_column()?);
            }
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = self.parse_datatype()?;
        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;
        while let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Primary => { self.expect(Token::Keyword(Keyword::Key))?; primary_key = true; }
                Keyword::Not => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(false); }
                Keyword::Null => { self.expect(Token::Keyword(Keyword::Null))?; nullable = Some(true); }
                Keyword::Default => { default = Some(self.parse_expression()?); }
                Keyword::Unique => { unique = true; }
                Keyword::Index => { index = true; }
                Keyword::References => { references = Some(self.next_ident()?); }
                _ => return Err(errinput!(\"unexpected keyword {kw} in column definition\")),
            }
        }
        Ok(ast::Column { name, datatype, primary_key, nullable, default, unique, index, references })
    }

    fn parse_datatype(&mut self) -> Result<DataType> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(match kw {
                Keyword::Bool | Keyword::Boolean => DataType::Boolean,
                Keyword::Int | Keyword::Integer => DataType::Integer,
                Keyword::Float | Keyword::Double => DataType::Float,
                Keyword::String | Keyword::Text | Keyword::Varchar => DataType::String,
                _ => return Err(errinput!(\"unexpected keyword {kw}\")),
            })
        } else {
            Err(errinput!(\"expected data type\"))
        }
    }

    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Table))?;
        let name = self.next_ident()?;
        let mut if_exists = false;
        if self.next_if_keyword() == Some(Keyword::If) {
            self.expect(Token::Keyword(Keyword::Exists))?;
            if_exists = true;
        }
        Ok(ast::Statement::DropTable { name, if_exists })
    }

    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::From))?;
        let table = self.next_ident()?;
        let mut rwhere = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            rwhere = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Delete { table, rwhere })
    }

    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Token::Keyword(Keyword::Into))?;
        let table = self.next_ident()?;
        let mut columns = None;
        self.expect(Token::OpenParen)?;
        if !self.next_is(Token::CloseParen) {
            columns = Some(vec![self.next_ident()?]);
            while self.next_is(Token::Comma) {
                columns.as_mut().unwrap().push(self.next_ident()?);
            }
        }
        self.expect(Token::CloseParen)?;
        self.expect(Token::Keyword(Keyword::Values))?;
        self.expect(Token::OpenParen)?;
        let mut values = Vec::new();
        values.push(self.parse_expression_list()?);
        while self.next_is(Token::Comma) {
            values.push(self.parse_expression_list()?);
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::Insert { table, columns, values })
    }

    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;
        self.expect(Token::Keyword(Keyword::Set))?;
        let mut set = BTreeMap::new();
        let col = self.next_ident()?;
        set.insert(col.clone(), None);
        self.expect(Token::Equal)?;
        set.get_mut(&col).unwrap().replace(self.parse_expression()?);
        let mut rwhere = None;
        if self.next_if_keyword() == Some(Keyword::Where) {
            rwhere = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Update { table, set, rwhere })
    }

    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;
        let from = self.parse_from_clause()?;
        let rwhere = self.parse_where_clause()?;
        let group_by = self.parse_group_by_clause()?;
        let having = self.parse_having_clause()?;
        let order_by = self.parse_order_by_clause()?;
        let offset = self.parse_offset_clause()?;
        let limit = self.parse_limit_clause()?;
        Ok(ast::Statement::Select { select, from, rwhere, group_by, having, order_by, offset, limit })
    }

    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        select.push(self.parse_select_item()?);
        while self.next_is(Token::Comma) {
            select.push(self.parse_select_item()?);
        }
        Ok(select)
    }

    fn parse_select_item(&mut self) -> Result<(ast::Expression, Option<String>)> {
        let expr = self.parse_expression()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if let ast::Expression::Column(None, name) = &expr {
            if self.next_if_keyword() != Some(Keyword::As) {
                alias = Some(name.clone());
            }
        }
        Ok((expr, alias))
    }

    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        self.expect(Token::Keyword(Keyword::From))?;
        let mut from = Vec::new();
        from.push(self.parse_from_table()?);
        while let Some(join_type) = self.parse_from_join()? {
            let right = self.parse_from_table()?;
            let mut predicate = None;
            if self.next_if_keyword() == Some(Keyword::On) {
                predicate = Some(self.parse_expression()?);
            }
            from.push(ast::From::Join { left: Box::new(from.pop().unwrap()), right: Box::new(right), r#type: join_type, predicate });
        }
        Ok(from)
    }

    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let mut alias = None;
        if self.next_if_keyword() == Some(Keyword::As) {
            alias = Some(self.next_ident()?);
        } else if alias.is_none() {
            alias = Some(name.clone());
        }
        Ok(ast::From::Table { name, alias })
    }

    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            Ok(Some(match kw {
                Keyword::Cross => ast::JoinType::Cross,
                Keyword::Inner => ast::JoinType::Inner,
                Keyword::Left => ast::JoinType::Left,
                Keyword::Right => ast::JoinType::Right,
                Keyword::Join => ast::JoinType::Inner,
                _ => return Err(errinput!(\"unexpected keyword {kw}\")),
            }))
        } else {
            Ok(None)
        }
    }

    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Where) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        self.expect(Token::Keyword(Keyword::Group))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut group_by = Vec::new();
        group_by.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            group_by.push(self.parse_expression()?);
        }
        Ok(group_by)
    }

    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Having) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        self.expect(Token::Keyword(Keyword::Order))?;
        self.expect(Token::Keyword(Keyword::By))?;
        let mut order_by = Vec::new();
        order_by.push(self.parse_order_by_item()?);
        while self.next_is(Token::Comma) {
            order_by.push(self.parse_order_by_item()?);
        }
        Ok(order_by)
    }

    fn parse_order_by_item(&mut self) -> Result<(ast::Expression, ast::Direction)> {
        let expr = self.parse_expression()?;
        let mut direction = ast::Direction::Ascending;
        if self.next_if_keyword() == Some(Keyword::Desc) {
            direction = ast::Direction::Descending;
        } else if self.next_if_keyword() == Some(Keyword::Asc) {
            direction = ast::Direction::Ascending;
        }
        Ok((expr, direction))
    }

    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Limit) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if self.next_if_keyword() == Some(Keyword::Offset) {
            Ok(Some(self.parse_expression()?))
        } else {
            Ok(None)
        }
    }

    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(Precedence::MIN)
    }

    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
        let mut lhs = self.parse_expression_atom()?;
        loop {
            if let Some(op) = self.parse_prefix_operator_at(min_precedence) {
                lhs = op.into_expression(lhs);
                continue;
            }
            if let Some(op) = self.parse_infix_operator_at(min_precedence) {
                let rhs_precedence = min_precedence + op.associativity();
                let rhs = self.parse_expression_at(rhs_precedence)?;
                lhs = op.into_expression(lhs, rhs);
                continue;
            }
            if let Some(op) = self.parse_postfix_operator_at(min_precedence)? {
                lhs = op.into_expression(lhs);
                continue;
            }
            break;
        }
        Ok(lhs)
    }

    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::True => ast::Expression::Literal(ast::Literal::Boolean(true)),
                Keyword::False => ast::Expression::Literal(ast::Literal::Boolean(false)),
                Keyword::Null => ast::Expression::Literal(ast::Literal::Null),
                Keyword::Infinity => ast::Expression::Literal(ast::Literal::Float(f64::INFINITY)),
                Keyword::NaN => ast::Expression::Literal(ast::Literal::Float(f64::NAN)),
                Keyword::Select => return Err(errinput!(\"subqueries not supported yet\")),
                _ => return Err(errinput!(\"unexpected keyword {kw}\")),
            });
        }
        if self.next_is(Token::OpenParen) {
            let expr = self.parse_expression()?;
            self.expect(Token::CloseParen)?;
            return Ok(expr);
        }
        if let Some(kw) = self.next_if_keyword() {
            return Ok(match kw {
                Keyword::Not => {
                    let expr = self.parse_expression()?;
                    ast::Expression::Operator(ast::Operator::Not(Box::new(expr)))
                }
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::NaN) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return Err(errinput!(\"expected NULL or NAN\"));
                    };
                    if neg {
                        ast::Expression::Operator(ast::Operator::Not(Box::new(
                            ast::Expression::Operator(ast::Operator::Is(
                                Box::new(ast::Expression::All),
                                lit,
                            )),
                        )))
                    } else {
                        ast::Expression::Operator(ast::Operator::Is(Box::new(ast::Expression::All), lit))
                    }
                }
                _ => return Err(errinput!(\"unexpected keyword {kw}\")),
            });
        }
        if self.next_is(Token::Minus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Negate(Box::new(expr))));
        }
        if self.next_is(Token::Plus) {
            let expr = self.parse_expression_atom()?;
            return Ok(ast::Expression::Operator(ast::Operator::Identity(Box::new(expr))));
        }
        let token = match self.lexer.next() {
            Some(Ok(t)) => t,
            Some(Err(e)) => return Err(e),
            None => return Err(errinput::<String>(\"unexpected end of input\")),
        };
        match token {
            Token::Number(s) => {
                return Ok(ast::Expression::Literal(match s.chars().position(|c| c == \".\") {
                    Some(_) => ast::Literal::Float(s.parse::<f64>().map_err(|_| errinput::<String>(\"invalid float\"))?),
                    None => ast::Literal::Integer(s.parse::<i64>().map_err(|_| errinput::<String>(\"invalid integer\"))?),
                }));
            }
            Token::String(s) => {
                return Ok(ast::Expression::Literal(ast::Literal::String(s)));
            }
            _ => {}
        }
        if self.next_is(Token::Asterisk) {
            return Ok(ast::Expression::All);
        }
        let table = self.next_ident()?;
        if self.next_is(Token::Period) {
            let column = self.next_ident()?;
            Ok(ast::Expression::Column(Some(table), column))
        } else {
            Ok(ast::Expression::Column(None, table))
        }
    }

    fn parse_expression_list(&mut self) -> Result<Vec<ast::Expression>> {
        let mut exprs = Vec::new();
        exprs.push(self.parse_expression()?);
        while self.next_is(Token::Comma) {
            exprs.push(self.parse_expression()?);
        }
        Ok(exprs)
    }

    fn parse_prefix_operator_at(&mut self, _min_precedence: Precedence) -> Option<PrefixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::Not => Some(PrefixOperator::Not),
                Keyword::Is => {
                    let neg = self.next_if_keyword() == Some(Keyword::Not);
                    let _lit = if self.next_if_keyword() == Some(Keyword::Null) {
                        ast::Literal::Null
                    } else if self.next_if_keyword() == Some(Keyword::NaN) {
                        ast::Literal::Float(f64::NAN)
                    } else {
                        return None;
                    };
                    if neg { Some(PrefixOperator::Not) } else { None }
                }
                _ => None,
            };
        }
        if self.next_is(Token::Minus) { return Some(PrefixOperator::Minus); }
        if self.next_is(Token::Plus) { return Some(PrefixOperator::Plus); }
        None
    }

    fn parse_infix_operator_at(&mut self, min_precedence: Precedence) -> Option<InfixOperator> {
        if let Some(kw) = self.next_if_keyword() {
            return match kw {
                Keyword::And => Some(InfixOperator::And),
                Keyword::Or => Some(InfixOperator::Or),
                Keyword::Like => Some(InfixOperator::Like),
                _ => None,
            };
        }
        if self.next_is(Token::Equal) { return Some(InfixOperator::Equal); }
        if self.next_is(Token::NotEqual) { return Some(InfixOperator::NotEqual); }
        if self.next_is(Token::GreaterThan) { return Some(InfixOperator::GreaterThan); }
        if self.next_is(Token::GreaterThanOrEqual) { return Some(InfixOperator::GreaterThanOrEqual); }
        if self.next_is(Token::LessThan) { return Some(InfixOperator::LessThan); }
        if self.next_is(Token::LessThanOrEqual) { return Some(InfixOperator::LessThanOrEqual); }
        if self.next_is(Token::Plus) { return Some(InfixOperator::Add); }
        if self.next_is(Token::Minus) { return Some(InfixOperator::Subtract); }
        if self.next_is(Token::Asterisk) { return Some(InfixOperator::Multiply); }
        if self.next_is(Token::Slash) { return Some(InfixOperator::Divide); }
        if self.next_is(Token::Caret) { return Some(InfixOperator::Exponentiate); }
        if self.next_is(Token::Percent) { return Some(InfixOperator::Remainder); }
        None
    }

    fn parse_postfix_operator_at(&mut self, _min_precedence: Precedence) -> Result<Option<PostfixOperator>> {
        if self.next_is(Token::Exclamation) {
            return Ok(Some(PostfixOperator::Factorial));
        }
        if self.next_is(Token::Keyword(Keyword::Is)) {
            let neg = self.next_is(Token::Keyword(Keyword::Not));
            let lit = if self.next_is(Token::Keyword(Keyword::Null)) {
                ast::Literal::Null
            } else if self.next_is(Token::Keyword(Keyword::NaN)) {
                ast::Literal::Float(f64::NAN)
            } else {
                return Err(errinput!(\"expected NULL or NAN\"));
            };
            return Ok(Some(if neg { PostfixOperator::IsNot(lit) } else { PostfixOperator::Is(lit) }));
        }
        Ok(None)
    }
}

type Precedence = u8;

enum Associativity { Left, Right }

impl Add<Associativity> for Precedence {
    type Output = Self;
    fn add(self, rhs: Associativity) -> Self {
        match rhs { Associativity::Left => self + 1, Associativity::Right => self }
    }
}

enum PrefixOperator { Minus, Not, Plus }

impl PrefixOperator {
    fn precedence(&self) -> Precedence { 100 }
    fn associativity(&self) -> Associativity { Associativity::Right }
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        match self {
            Self::Minus => ast::Expression::Operator(ast::Operator::Negate(Box::new(rhs))),
            Self::Not => ast::Expression::Operator(ast::Operator::Not(Box::new(rhs))),
            Self::Plus => ast::Expression::Operator(ast::Operator::Identity(Box::new(rhs))),
        }
    }
}

enum InfixOperator {
    Add, And, Divide, Equal, Exponentiate, GreaterThan, GreaterThanOrEqual,
    LessThan, LessThanOrEqual, Like, Multiply, NotEqual, Or, Remainder, Subtract,
}

impl InfixOperator {
    fn precedence(&self) -> Precedence {
        match self {
            Self::Or => 10, Self::And => 20,
            Self::Equal | Self::NotEqual | Self::LessThan | Self::LessThanOrEqual |
            Self::GreaterThan | Self::GreaterThanOrEqual | Self::Like => 30,
            Self::Add | Self::Subtract => 40,
            Self::Multiply | Self::Divide | Self::Remainder => 50,
            Self::Exponentiate => 60,
        }
    }
    fn associativity(&self) -> Associativity { Associativity::Left }
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Add => ast::Expression::Operator(Add(Box::new(lhs), Box::new(rhs))),
            Self::And => ast::Expression::Operator(And(Box::new(lhs), Box::new(rhs))),
            Self::Divide => ast::Expression::Operator(Divide(Box::new(lhs), Box::new(rhs))),
            Self::Equal => ast::Expression::Operator(Equal(Box::new(lhs), Box::new(rhs))),
            Self::Exponentiate => ast::Expression::Operator(Exponentiate(Box::new(lhs), Box::new(rhs))),
            Self::GreaterThan => ast::Expression::Operator(GreaterThan(Box::new(lhs), Box::new(rhs))),
            Self::GreaterThanOrEqual => ast::Expression::Operator(GreaterThanOrEqual(Box::new(lhs), Box::new(rhs))),
            Self::LessThan => ast::Expression::Operator(LessThan(Box::new(lhs), Box::new(rhs))),
            Self::LessThanOrEqual => ast::Expression::Operator(LessThanOrEqual(Box::new(lhs), Box::new(rhs))),
            Self::Like => ast::Expression::Operator(Like(Box::new(lhs), Box::new(rhs))),
            Self::Multiply => ast::Expression::Operator(Multiply(Box::new(lhs), Box::new(rhs))),
            Self::NotEqual => ast::Expression::Operator(NotEqual(Box::new(lhs), Box::new(rhs))),
            Self::Or => ast::Expression::Operator(Or(Box::new(lhs), Box::new(rhs))),
            Self::Remainder => ast::Expression::Operator(Remainder(Box::new(lhs), Box::new(rhs))),
            Self::Subtract => ast::Expression::Operator(Subtract(Box::new(lhs), Box::new(rhs))),
        }
    }
}

enum PostfixOperator { Factorial, Is(ast::Literal), IsNot(ast::Literal) }

impl PostfixOperator {
    fn precedence(&self) -> Precedence { 70 }
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Factorial => ast::Expression::Operator(Factorial(Box::new(lhs))),
            Self::Is(lit) => ast::Expression::Operator(Is(Box::new(lhs), lit)),
            Self::IsNot(lit) => {
                let is_expr = ast::Expression::Operator(Is(Box::new(lhs), lit));
                ast::Expression::Operator(Not(Box::new(is_expr)))
            }
        }
    }
}
